// Две роли · spec: specs/location-map.md 3.4 · кейс .qa/tests/location-map/PRIV-01.md
// Регресс бага приватности: nearby_live отдаёт другим только примерное место. Принятые пользователем оговорки (11.11) —
// маленький сдвиг у одного пользователя (48 м) и «прыжок» по сетке при сдвиге — НЕ проверяются: минимального сдвига нет.
import { test, expect } from '../../fixtures';
import { rowId, userIdOf, GEO } from './map-helpers';
import { setupPair, teardownPair, metersBetween, decimals, fetchNearbyStable, type Pair } from './pair-helpers';

test.describe('פרטיות מיקום — nearby_live', () => {
  test.describe.configure({ timeout: 240_000 });
  test('координаты другого — не точные: ≤4 знаков, в пределах ~700 м, те же при повторе; расстояние шагом 100 м @iphone @data (#f3fc59)', async ({ asUser }) => {
    let p: Pair | undefined;
    try {
      // user2 записывает своё точное место (эмуляция), free — наблюдатель.
      p = await setupPair(asUser, true);
      const { free } = p;
      const id = userIdOf('user2');
      const real = { lat: GEO.user2.latitude, lng: GEO.user2.longitude };

      const seen: { lat: number; lng: number }[] = [];
      for (let i = 0; i < 3; i++) {
        const row = (await fetchNearbyStable(free)).find((r) => rowId(r) === id);
        expect(row, 'user2 в ответе nearby_live у free').toBeTruthy();
        // п.1: не больше 4 знаков после точки (было 13).
        expect(decimals(row!.lat), `lat ${row!.lat}`).toBeLessThanOrEqual(4);
        expect(decimals(row!.lng), `lng ${row!.lng}`).toBeLessThanOrEqual(4);
        const at = { lat: Number(row!.lat), lng: Number(row!.lng) };
        // п.2: примерное место — в окрестности реального (обещание программиста: до ~700 м; запас 100 м).
        expect(metersBetween(at, real), 'расстояние примерной точки от реальной, м').toBeLessThanOrEqual(800);
        // п.4: расстояние шагом 100 м.
        expect(Number(row!.distance_m) % 100, `distance_m ${row!.distance_m}`).toBe(0);
        seen.push(at);
      }
      // п.3: повторные запросы — те же примерные координаты (нельзя усреднить).
      for (const s of seen) expect(s).toEqual(seen[0]);

      // п.4: в карточке на карте — то же округлённое расстояние.
      const last = (await fetchNearbyStable(free)).find((r) => rowId(r) === id)!;
      const d = Number(last.distance_m);
      const label = d >= 1000 ? `${(d / 1000).toFixed(1).replace(/\.0$/, '')} ק״מ` : `${d} מ׳`;
      await expect(free.getByRole('button', { name: /QA דתי, 56/ }).filter({ hasText: label }).first()).toBeVisible();
    } finally {
      await teardownPair(p);
    }
  });

  test('своё место «אני» отправляется точно: record_location = эмулированные координаты @iphone @data (#f3fc59)', async ({ asUser }) => {
    let p: Pair | undefined;
    try {
      p = await setupPair(asUser, true);
      const { user2 } = p;
      const req = user2.waitForRequest((r) => r.url().includes('/rpc/record_location') && r.method() === 'POST');
      await user2.reload();
      const body = (await req).postDataJSON() as Record<string, unknown>;
      const nums = Object.values(body).filter((v) => typeof v === 'number') as number[];
      // п.5: «אני» — точное место устройства (на сервер уходит реальная точка; другим — примерная).
      expect(nums.some((v) => Math.abs(v - GEO.user2.latitude) < 1e-4), `lat в ${JSON.stringify(body)}`).toBe(true);
      expect(nums.some((v) => Math.abs(v - GEO.user2.longitude) < 1e-4), `lng в ${JSON.stringify(body)}`).toBe(true);
    } finally {
      await teardownPair(p);
    }
  });
});
